package textcipher

import (
	"encoding/base64"
	"strings"
	"testing"
)

func TestJavaToken(t *testing.T) {
	// Generated by the existing Java Pbkdf2AesGcmTextEncryptor.
	token := "pte1.pbkdf2-sha256.600000.ttx25ZtD0_Arku7WcWPdBQ.aNny3DgvUYqUk_xu.KMUCACzhb6S1Q61bFj6994QqGtYW6tOIdMFh3DXBVyMjaKofUbIlX9bl3ynn"
	got, err := Decrypt("密碼🔑", token)
	if err != nil || got != "中文、English、Emoji 🔐" {
		t.Fatalf("Decrypt = %q, %v", got, err)
	}
}

func TestRoundTripAndAuthentication(t *testing.T) {
	for _, plain := range []string{"", "中文、English、Emoji 🔐"} {
		token, err := Encrypt("密碼🔑", plain)
		if err != nil {
			t.Fatal(err)
		}
		other, err := Encrypt("密碼🔑", plain)
		if err != nil {
			t.Fatal(err)
		}
		if token == other {
			t.Fatal("encryption must use fresh randomness")
		}
		got, err := Decrypt("密碼🔑", token)
		if err != nil || got != plain {
			t.Fatalf("round trip = %q, %v", got, err)
		}
		if _, err := Decrypt("wrong", token); err == nil {
			t.Fatal("accepted incorrect password")
		}
		parts := strings.Split(token, ".")
		payload, _ := base64.RawURLEncoding.DecodeString(parts[5])
		payload[0] ^= 1
		parts[5] = base64.RawURLEncoding.EncodeToString(payload)
		if _, err := Decrypt("密碼🔑", strings.Join(parts, ".")); err == nil {
			t.Fatal("accepted modified ciphertext")
		}
		parts = strings.Split(token, ".")
		parts[2] = "600001"
		if _, err := Decrypt("密碼🔑", strings.Join(parts, ".")); err == nil {
			t.Fatal("accepted modified header")
		}
	}
}

func TestInvalidTokens(t *testing.T) {
	for _, token := range []string{
		"", "invalid", "pte2.pbkdf2-sha256.600000.a.b.c",
		"pte1.other.600000.a.b.c", "pte1.pbkdf2-sha256.0.a.b.c",
		"pte1.pbkdf2-sha256.10000001.a.b.c", "pte1.pbkdf2-sha256.no.a.b.c",
		"pte1.pbkdf2-sha256.600000.!.b.c", "pte1.pbkdf2-sha256.600000.YQ.Yg.Yw",
	} {
		if _, err := Decrypt("password", token); err == nil {
			t.Errorf("accepted %q", token)
		}
	}
	if _, err := Encrypt("", "text"); err == nil {
		t.Fatal("accepted empty password")
	}
	if _, err := Decrypt("", "token"); err == nil {
		t.Fatal("accepted empty password")
	}
}
